The Herr complex
We first review some results from $p$-adic Hodge theory. Let $F$ be a finite extension of $\QQ_p$. Let $T\in\Rep_{\mathbb Z_p}(\mathcal{G}_{\QQ_p})$. Recall the following result from~\cite{herr98} (see also~\cite[\S 2]{cherbonniercolmez99}). Let $\gamma$ be a topological generator of $\Gamma_F$. For $f=\varphi$ or $\psi$, define the complex
   \[ \mathcal{C}^\bullet_{f,\gamma}\big(\mathbb D_F(T)\big): 0\rightarrow \mathbb D_F(T)\rTo^{\alpha_f}\mathbb D_F(T)\oplus\mathbb D_F(T)\rTo^{\beta_f}\mathbb D_F(T)\rightarrow 0,\]
   where $\alpha_f(x)=\big((\gamma-1)x,(f-1)x\big)$ and $\beta_f(x,y)=(f-1)x-(\gamma-1)y$. Denote by $H^i\big(\mathcal{C}^\bullet_{f,\gamma}(\mathbb D_F(V))\big)$ the $i$-th cohomology group of the complex. 

   \begin{theorem}
    For $f=\varphi$ or $\psi$, $H^i\big(\mathcal{C}^\bullet_{f,\gamma}(\mathbb D_F(T))\big)$ is canonically isomorphic to $H^i(F,T)$. In particular, if $(x,y)\in\mathbb D_F(T)^{\oplus 2}$ satisfies $\beta_\varphi(x,y)=0$, then the corresponding cohomology class in $H^1(F,T)$ is given by the cocycle
    \[ c_{(x,y)}: \sigma\mapsto \frac{\sigma-1}{\gamma-1}x-(\sigma-1)z,\]
    where $z\in\mathbb A\otimes_{\ZZ_p}T$ is such that $(\varphi-1)z=y$.
   \end{theorem}

   \begin{theorem}\label{comp}
    We have an $\Lambda(\Gamma_F)$-equivariant isomorphism $H^1_{\Iw}(F,T)\cong\mathbb D_{F}(T)^{\psi=1}$. If $F_\infty$ is Galois over $\QQ_p$, then the isomorphism is compatible with the action of $G=\Gal(F_\infty\slash \QQ_p)$.
   \end{theorem}
   \begin{proof}
    See \cite[Th\'eor\`eme II.1.3]{cherbonniercolmez99}.
   \end{proof}

   From now on, we will identify  $H^1_{\Iw}(F,T)$ with $\mathbb D_{F}(T)^{\psi=1}$ under the isomorphism given by Theorem~\ref{comp}.

The local conditions
Write $\mathbb D_K^\dagger(T)$ for the overconvergent $(\varphi,\Gamma)$-module of $T$ over $K$. It is clear from the definition that
  \[ \mathbb D^\dagger_K(T)=\mathbb A^\dagger_K\otimes_{\mathbb A^+_{\QQ_p}}\mathbb N(T),\]
  so in particular the basis $n_1,n_2$ of $\mathbb N(T)$ given in Section~\ref{supersingular} is a basis of $\mathbb D^\dagger_K(T)$ over $\mathbb A^\dagger_K$.

  As shown in \cite[Proposition III.3.2]{cherbonniercolmez99}, we have 
  $\mathbb D^\dagger_K(T)^{\psi=1}\subset \mathbb D^{\dagger,N}_K(T)$  for $N\ge N(K,V)$. Fix such an $N$; note that it is not uniquely defined. Let $x\in \mathbb D^\dagger_K(T)^{\psi=1}$. Then as in Section~\ref{supersingular}, we can write 
  \[x=x_1v_1+x_2v_2=x_1'n_1+x_2'n_2\]
  with $x_i\in\mathbb B^{\dagger,N}_{\rig,K}$ and $x_i'\in \mathbb B^{\dagger,N}_{K}$ for $i=1,2$.

  \begin{lemma}\label{triv0}
   Let $x\in \mathbb D^\dagger_K(T)^{\psi=1}$, then
   \[\Tr_{K_n/K_{n-1}}\circ\theta\circ\varphi^{-n}(x_1)=-\theta\circ\varphi^{2-n}(x_1)\]
   for all odd integers $n\ge N+2$ and
   \[\Tr_{K_n/K_{n-1}}\circ\theta\circ\varphi^{-n}(x_2)=-\theta\circ\varphi^{2-n}(x_2)\]
   for all even integers $n\ge N+2$.
  \end{lemma}
  \begin{proof}
   By definitions, we have $\varphi(\log^+(1+\pi))=\frac{p}{q}\log^-(1+\pi)$ and $\varphi(\log^-(1+\pi))=\log^+(1+\pi)$, and that similar relations hold when replacing $\varphi$ by $\psi$. The relations \eqref{basechange} therefore imply that
   \begin{eqnarray}
    \varphi(x_1)+p\psi(x_1)&=&\left(\varphi(x_1')+\psi(qx_1')\right)\log^+(1+\pi);\label{log1}\\
    \varphi(x_2)+p\psi(x_2)&=&\left(\varphi(x_2')+q\psi(x_2')\right)p/q\log^-(1+\pi).\label{log2}
   \end{eqnarray}
   If $n\ge 2$ is an even integer, then $\theta\circ\varphi^{-n}\left(\log^+(1+\pi)\right)=0$. Therefore, \eqref{log1} implies that
   \[
   \theta\circ\varphi^{-n+1}(x_1)+\theta\circ\varphi^{-n-1}\left(p\varphi\circ\psi(x_1)\right)=0.
   \] 
   Recall that $p\varphi\circ\psi=\Tr_{\mathbb B/\varphi(\mathbb B)}$, so Lemma~\ref{comptrace} implies the first part of the lemma. Similarly, the second half the lemma follows from \eqref{log2} and the fact that 
   \[\theta\circ\varphi^{-n}\left(p/q\log^-(1+\pi)\right)=0\]
   for all odd integers $n\ge 3$.
  \end{proof}

  \begin{proposition}\label{des1}
   Let $x\in \mathbb D^\dagger_K(T)^{\psi=1}$, then $x\in H^1_{\Iw}(K,T)^i$ if and only if
   \[\Tr_{K_n/K_{n-1}}\circ\theta\circ\varphi^{-n}(x_i)=-\theta\circ\varphi^{2-n}(x_i)\]
   for all $n\ge N+2$. 
  \end{proposition}
  \begin{proof}
   If $x\in H^1_{\Iw}(K,T)^i$, then 
   \[
   \varphi^2(x_i)=-p\varphi\circ\psi(x_i)=-\Tr_{\mathbb B/\varphi(\mathbb B)}(x_i).
   \]
   On applying $\theta\circ\varphi^{-n}$ to both sides, we have by Lemma~\ref{comptrace} that
   \[
   \theta\circ\varphi^{2-n}(x_i)=-\Tr_{K_n/K_{n-1}}\circ\theta\circ\varphi^{-n}(x_i)
   \]
   as required.

   Conversely, we assume that 
   \[
   \Tr_{K_n/K_{n-1}}\circ\theta\circ\varphi^{-n}(x_i)=-\theta\circ\varphi^{2-n}(x_i)
   \]
   for all $n\ge N+2$. Then $\theta\circ\varphi^{-n}\left(\varphi(x_i)+p\psi(x_i)\right)=0$ by Lemma~\ref{comptrace}. Our assumption implies that $\varphi(x_1')+\psi(qx_1')=0$ for $i=1$ and $\varphi(x_2')+q\psi(x_2')=0$ for $i=2$ by Lemma~\ref{vanish} and the equations \eqref{log1} and \eqref{log2}. Therefore, we have $x\in H^1_{\Iw}(K,T)^i$ as required.
  \end{proof}

  \begin{remark}
   By Lemma~\ref{triv0}, we can rewrite Proposition \ref{des1} as follows:
   \begin{eqnarray*}
    H^1_{\Iw}(K,T)^1&=&\left\{x\in \mathbb D^\dagger_K(T)^{\psi=1}:\Tr_{K_n/K_{n-1}}\circ\theta\circ\varphi^{-n}(x_1)=-\theta\circ\varphi^{2-n}(x_1)\text{ for all even }n\ge N+2\right\};\\
    H^1_{\Iw}(K,T)^2&=&\left\{x\in \mathbb D^\dagger_K(T)^{\psi=1}:\Tr_{K_n/K_{n-1}}\circ\theta\circ\varphi^{-n}(x_2)=-\theta\circ\varphi^{2-n}(x_2)\text{ for all odd }n\ge N+2\right\}.
   \end{eqnarray*}
  \end{remark}

  We can now describe $H^1_{\Iw}(K,T)^i$ as follows.

  \begin{corollary}\label{trace}
   We have
   \begin{eqnarray*}
    H^1_{\Iw}(K,T)^1&=&\left\{x\in \mathbb D_K(T)^{\psi=1}:\exp^*_{K_n}\circ h^1_{\Iw,n}(x)\in K_{n-1}\cdot v_1\text{ for all odd }n\ge N+1\right\},\\
    H^1_{\Iw}(K,T)^2&=&\left\{x\in \mathbb D_K(T)^{\psi=1}:\exp^*_{K_n}\circ h^1_{\Iw,n}(x)\in K_{n-1}\cdot v_1\text{ for all even }n\ge N+1\right\}.
   \end{eqnarray*}
  \end{corollary}
  \begin{proof}
   By \cite[Th\'eor\`eme IV.2.1]{cherbonniercolmez99}, 
   \[ \exp^*_{K_n}\circ h^1_{\Iw,n}(x)= \partial_V\circ \varphi^{-n}(x)\]
   for all $n\geq N$. Since
   \[ \partial_V\circ \varphi^{-n}(x)=\theta\circ\varphi^{-n}(x_1)\varphi^{-n}(v_1)+\theta\circ\varphi^{-n}(x_2)\varphi^{-n}(v_2)\]
    and the image of $\exp^*_{K_n}$ lies in $K_n\otimes{\Fil}^0\mathbb D_{\cris}(V)$, it follows that 
   \[ \exp^*_{K_n}\circ h^1_{\Iw,n}(x)=
    \begin{cases}
    (-1)^mp^{-m}\theta\circ\varphi^{-2m}(x_1)v_1 & \text{ if $n=2m\ge N$}, \\
    (-1)^mp^{-m}\theta\circ\varphi^{-(2m+1)}(x_2)v_1 & \text{ if $n=2m+1\ge N$}.
    \end{cases}
   \]
   Extend the trace map $\Tr_{K_n/K_{n-1}}$ to the map $\Tr_{K_n/K_{n-1}}\circ\mathrm{id}$ on $K_n\otimes_{\QQ_p}\mathbb D_{\cris}(V)$. Then, $x\in H^1_{\Iw}(K,T)^1$ if and only if
   \[
   \Tr_{K_n/K_{n-1}}\circ\exp^*_{K_n}\circ h^1_{\Iw,n}(x)=p^{-1}\exp^*_{K_{n-2}}\circ h^1_{\Iw,{n-2}}(x)
   \]
   for all even $n\ge N+2$. But 
   \[
   \Tr_{K_m\slash K_{m-1}}\circ \exp^*_{K_{m}} =\exp^*_{K_{m-1}}\circ {\cor}_{K_m\slash K_{m-1}}
   \]
   for all $m\ge0$, so we deduce that $x\in H^1_{\Iw}(K,T)^1$ if and only if
   \[
   \exp^*_{K_{n-1}}\circ h^1_{\Iw,n-1}(x)=p^{-1}\Tr_{K_{n-1}/K_{n-2}}\circ\exp^*_{K_{n-1}}\circ h^1_{\Iw,n-1}(x)
   \]
   for all even $n\ge N-2$. 
  \end{proof}

  As a important consequence, we can characterise $H^1_{\Iw}(K,T)^i$ completely in terms of the conditions on the finite levels:

  \begin{corollary}\label{sameinv}
   For $i\in\{1,2\}$ and $n\geq N+1$, define
   \[ H_N^1(K_n,T)^{(i)}=\left\{x\in H^1(K_n,T):\Tr_{K_n\slash K_m}\circ\exp^*_{K_n}(x)\in K_{m-1}\cdot v_1\hspace{2ex}\text{for all $m\in S_{N,i}^n$}\right\}.\]
   where $S_{N,i}^n$ is given by
   \begin{eqnarray*}
    S_{N,1}^n&=&\left\{m\in[N+1,n]:m\text{ odd }\right\},\\
    S_{N,2}^n&=&\left\{m\in[N+1,n]:m\text{ even }\right\}.
   \end{eqnarray*}
   Then $H^1_{\Iw}(K,T)^i=\varprojlim H_N^1(K_n,T)^{(i)}$.
  \end{corollary}
  \begin{proof}
   Immediate from Corollary~\ref{trace}.
  \end{proof}


 {\bf Notation.} Let $F$ be a finite extension of $\QQ_p$. For an integer $n\ge1$, we write $F_n^{(0)}=\ker(\Tr_{F_n/F_{n-1}})$. Then we have
  \begin{equation}\label{pro}
  F_n=F\oplus\bigoplus_{i=1}^nF_i^{(0)}.
  \end{equation}

  \begin{lemma}\label{3des}
   Let $n\ge N+1$ be an integer, then
   \[
    H_N^1(K_n,T)^{(i)}=\left(\exp^*_{K_n}\right)^{-1}\left(K_N\oplus\bigoplus_{m\in S_{N,i'}^n}K_{m}^{(0)}\cdot v_1\right)
   \]
   where $\{i'\}=\{1,2\}\setminus\{i\}$.
  \end{lemma}
  \begin{proof}
   Let $x\in K_n$. By definition, the projection of $x$ under \eqref{pro} into $K_m^{(0)}$ is zero if and only if $\Tr_{K_n/K_{m}}x\in K_{m-1}$. Hence the result.
  \end{proof}

  From now on, we make the following assumption. 

  \begin{assumption}\label{assumptionptorsion}
   $E(K_\infty)$ has no $p$-torsion.
  \end{assumption}

  Note that this is satisfied for example when $[K:\QQ_p]$ is a power of $p$. 
  \begin{remark}
   Assumption~\ref{assumptionptorsion} implies that the natural map $H^1(K_n,T)\rTo H^1(K_n,V)$ is injective for all $n\ge0$. In particular, we may embed $H^1(K_n,T)$ into $H^1(K_n,V)$ and consider the former as a lattice inside the latter. 
  \end{remark}


  \begin{proposition}\label{describingortho}
   Let $H^1_{f,N,(i)}(K_n,T)$ be the exact annihilator of $H_N^1(K_n,T)^{(i)}$ under the Tate pairing. Then 
   \[
     H_{f,N,(i)}^1(K_n,T) = H^1(K_n,T)\cap \exp_{K_n}\left( \bigoplus_{m\in S_{N,i}^n}K_{m}^{(0)} \otimes\mathbb D_{\cris}(V) \right)
   \]
  \end{proposition}
  \begin{proof}
By Lemma~\ref{3des}, we have
   \begin{equation}\label{E}
    H^1_{f,N,(1)}(K_n,T)=\left(\left(\exp^*_{K_n}\right)^{-1}\left(K_N\oplus\bigoplus_{m\in S_{N,i'}^n}K_{m}^{(0)}\cdot v_1\right)\right)^{\bot_{[,]}}
   \end{equation}
where $(\star)^{\bot_{[,]}}$ denotes the exact annihilator of $\star$ under the pairing $[\sim,\sim]$. But
\[
[\exp_{K_n}(\sim),\sim]=\Tr_{K_n/\QQ_p}\langle\sim,\exp^*_{K_n}(\sim)\rangle.
\] 
where $\langle\sim,\sim\rangle$ is the pairing
\[
\langle\sim,\sim\rangle:\Big(K_n\otimes\mathbb D_{\cris}(V)\Big)\times\Big(K_n\otimes\mathbb D_{\cris}(V)\Big)\rightarrow K_n.
\] 
Therefore,
\begin{equation}\label{ortho}
x\in\left(\left(\exp^*_{K_n}\right)^{-1}\left(\star\cdot v_1\right)\right)^{\bot_{[,]}}\quad\text{if and only if}\quad x\in\exp_{K_n}\left((\star)^\bot\otimes\mathbb D_{\cris}(V)\right)
\end{equation}
     where $(\star)^\bot$ denotes the orthogonal complement of $\star$ under the pairing
     \begin{align*}
      K_n\times K_n &\rightarrow \QQ_p\\
      (x,y) &\mapsto \Tr_{K_n/\QQ_p}(xy).
     \end{align*}
    By linear algebra, we have
\[
\left(K_N\oplus\bigoplus_{m\in S_{N,i'}^n}K_{m}^{(0)}\right)^\bot=\bigoplus_{m\in S_{N,i}^n}K_{m}^{(0)}.
\]
Hence the result on combining \eqref{E} with \eqref{ortho}.
  \end{proof}


Recall that the exponential map $\exp_{K_n}$ gives an isomorphism
\[
\exp_{K_n}:K_n\otimes\mathbb D_{\cris}(V)/\Fil^0\mathbb D_{\cris}(V)\rTo H^1_f(K_n,V).
\]
We write $\exp_{K_n}^{-1}$ for its inverse.

By \eqref{pro}, we may define a projection map
\[
P_{N,i}^n:K_n\rTo K_N\oplus\bigoplus_{m\in S_{N,i'}^n}K_m^{(0)}.
\]
We can then rewrite Proposition~\ref{describingortho} as follows. 

\begin{corollary}
For $i=1,2$, we have
\[
 H_{f,N,(i)}^1(K_n,T) = \left\{x\in H_{f}^1(K_n,T):\left(P_{N,i}^n\otimes{\rm id}\right)\circ\exp_{K_n}^{-1}(x)=0\right\}.
\]
\end{corollary}
\begin{proof}
Note that
\[
K_n=\left(K_N\oplus\bigoplus_{m\in S_{N,i'}^n}K_m^{(0)}\right)\oplus\left( \bigoplus_{m\in S_{N,i}^n}K_{m}^{(0)}\right).
\]
Therefore, 
\[
\left(P_{N,i}^n\otimes{\rm id}\right)\circ\exp_{K_n}^{-1}(x)=0\quad\text{if and only if}\quad\exp_{K_n}^{-1}(x)\in \bigoplus_{m\in S_{N,i}^n}K_{m}^{(0)}\otimes\mathbb D_{\cris}(V)/\Fil^0\mathbb D_{\cris}(V).
\]
\end{proof}



   Recall that we have a commutative diagram








  \begin{diagram}
   {\rm tan}(\hat{E}\slash K_n) & \lTo^{\supset \hspace{3ex}} & \log_{\hat{E}}(\mathcal{O}_{K_n}) & \lTo^{\log_{\hat{E}}}& \hat{E}(\mathcal{O}_{K_n}) & \rTo^{\subset} & \hat{E}(\mathcal{O}_{K_n})\otimes \QQ_p \\
   \dTo^{\cong}_i           & & & & &               & \dTo^{\delta} \\
   K_n\otimes \mathbb D_{\cris}(V)\slash \Fil^0\mathbb D_{\cris}(V) & & & \rTo^{\exp_{K_n}} & & & H^1(K_n,V)
  \end{diagram}
  where $\delta$ is the Kummer map. If we identify the image of $\hat{E}(\mathcal{O}_{K_n})$ under $\delta$ with $H^1_f(K_n,T)$, we have:

   \begin{corollary}\label{rewrite}
    For $i\in\{1,2\}$, the image of $H_{f,N,(i)}^1(K_n,T)$ inside $\hat{E}(\mathcal{O}_{K_n})$ coincides with
    \begin{align*}
    \hat{E}_N^i(\mathcal{O}_{K_n})   :=& \left\{x\in\hat{E}(\mathcal{O}_{K_n}): \Tr_{K_n/K_m}x\in \hat{E}(\mathcal{O}_{K_{m-1}})\text{ for all }m\in S_{N,i'}^n \text{ and }\Tr_{K_n/K_N}x=0\right\}\\
    =&\left\{x\in\hat{E}(\mathcal{O}_{K_n}):P_{N,i}^n\circ\log_{\hat{E}}(x)=0\right\}.
    \end{align*}
   \end{corollary}
   \begin{proof}
    By the comutative diagram above and Proposition~\ref{describingortho}, we have 
    \[
     \delta(x)\in H_{f,N,(i)}^1(K_n,T)\quad\text{if and only if}\quad i\circ\log_{\hat{E}}(x)\in \bigoplus_{m\in S_{N,i}^n}K_{m}^{(0)}\otimes\mathbb D_{\cris}(V)/\Fil^0\mathbb D_{\cris}(V).
    \] 
    Since $\log_{\hat{E}}$ is injective (by Assumption~\ref{assumptionptorsion}) and compatible with the trace maps, we are done.
   \end{proof}

