   \[ \mathcal{C}^\bullet_{f,\gamma}\big(\mathbb D_F(T)\big): 0\rightarrow \mathbb D_F(T)\rTo^{\alpha_f}\mathbb D_F(T)\oplus\mathbb D_F(T)\rTo^{\beta_f}\mathbb D_F(T)\rightarrow 0,\]
   where $\alpha_f(x)=\big((\gamma-1)x,(f-1)x\big)$ and $\beta_f(x,y)=(f-1)x-(\gamma-1)y$. Denote by $H^i\big(\mathcal{C}^\bullet_{f,\gamma}(\mathbb D_F(V))\big)$ the $i$-th cohomology group of the complex. 

   \begin{theorem}
    For $f=\varphi$ or $\psi$, $H^i\big(\mathcal{C}^\bullet_{f,\gamma}(\mathbb D_F(T))\big)$ is canonically isomorphic to $H^i(F,T)$. In particular, if $(x,y)\in\mathbb D_F(T)^{\oplus 2}$ satisfies $\beta_\varphi(x,y)=0$, then the corresponding cohomology class in $H^1(F,T)$ is given by the cocycle
    \[ c_{(x,y)}: \sigma\mapsto \frac{\sigma-1}{\gamma-1}x-(\sigma-1)z,\]
    where $z\in\mathbb A\otimes_{\ZZ_p}T$ is such that $(\varphi-1)z=y$.
   \end{theorem}

   \begin{theorem}\label{comp}
    We have an $\Lambda(\Gamma_F)$-equivariant isomorphism $H^1_{\Iw}(F,T)\cong\mathbb D_{F}(T)^{\psi=1}$. If $F_\infty$ is Galois over $\QQ_p$, then the isomorphism is compatible with the action of $G=\Gal(F_\infty\slash \QQ_p)$.
   \end{theorem}
   \begin{proof}
    See \cite[Th\'eor\`eme II.1.3]{cherbonniercolmez99}.
   \end{proof}

   From now on, we will identify  $H^1_{\Iw}(F,T)$ with $\mathbb D_{F}(T)^{\psi=1}$ under the isomorphism given by Theorem~\ref{comp}.

